5	/// <summary>
6	/// Moves an invoice through its lifecycle: Draft -> PendingApproval -> Approved or Rejected.
7	/// Approvals are limited by the approver's role (see ApprovalLimits). Every rule is checked
8	/// before anything on the invoice is assigned, so a refused approval changes nothing.
9	/// </summary>
10	public class ApprovalService
11	{
12	    private readonly IInvoiceRepository _repository;
13	
14	    public ApprovalService(IInvoiceRepository repository)
15	    {
16	        _repository = repository;
17	    }
18	
19	    public Invoice Submit(string invoiceId)
20	    {
21	        var invoice = Find(invoiceId);
22	
23	        if (invoice.Status != InvoiceStatus.Draft)
24	        {
25	            throw new InvalidOperationException(
26	                $"Invoice {invoiceId} is {invoice.Status}; only drafts can be submitted.");
27	        }
28	
29	        invoice.Status = InvoiceStatus.PendingApproval;
30	        _repository.Update(invoice);
31	        return invoice;
32	    }
33	
34	    public Invoice Approve(string invoiceId, Approver approver)
35	    {
36	        ArgumentNullException.ThrowIfNull(approver);
37	        if (string.IsNullOrWhiteSpace(approver.Username))
38	        {
39	            throw new ArgumentException("An approver name is required to approve an invoice.", nameof(approver));
40	        }
41	
42	        var invoice = Find(invoiceId);
43	        EnsurePending(invoice);
44	        EnsureWithinLimit(invoice, approver);
45	
46	        invoice.Status = InvoiceStatus.Approved;
47	        invoice.DecidedBy = approver.Username;
48	        invoice.DecidedAt = DateTime.UtcNow;
49	        _repository.Update(invoice);
50	        return invoice;
51	    }
52	
53	    public Invoice Reject(string invoiceId, string approver, string reason)
54	    {
55	        if (string.IsNullOrWhiteSpace(reason))
56	        {
57	            throw new ArgumentException("A reason is required to reject an invoice.", nameof(reason));
58	        }
59	
60	        var invoice = Find(invoiceId);
61	        EnsurePending(invoice);
62	
63	        invoice.Status = InvoiceStatus.Rejected;
64	        invoice.DecidedBy = approver;
65	        invoice.DecidedAt = DateTime.UtcNow;
66	        invoice.DecisionNote = reason;
67	        _repository.Update(invoice);
68	        return invoice;
69	    }
70	
71	    private Invoice Find(string invoiceId) =>
72	        _repository.GetById(invoiceId)
73	        ?? throw new KeyNotFoundException($"Invoice {invoiceId} was not found.");
74	
75	    private static void EnsurePending(Invoice invoice)
76	    {
77	        if (invoice.Status != InvoiceStatus.PendingApproval)
78	        {
79	            throw new InvalidOperationException(
80	                $"Invoice {invoice.Id} is {invoice.Status}; only pending invoices can be decided.");
81	        }
82	    }
83	
84	    private static void EnsureWithinLimit(Invoice invoice, Approver approver)
85	    {
86	        var limit = ApprovalLimits.LimitFor(approver.Role)
87	            ?? throw new ApprovalDeniedException(
88	                $"{approver.Username} has role '{approver.Role}', which cannot approve invoices.");
89	
90	        if (invoice.Amount > limit)
91	        {
92	            var whoCanApprove = invoice.Amount <= ApprovalLimits.DirectorLimit
93	                ? "A Director must approve it."
94	                : $"Invoices above {Money(ApprovalLimits.DirectorLimit)} need two approvers.";
95	            throw new ApprovalDeniedException(
96	                $"Invoice {invoice.Id} is {Money(invoice.Amount)}, which is above the {approver.Role} limit of {Money(limit)}. {whoCanApprove}");
97	        }
98	    }
99	
100	    private static string Money(decimal amount) => amount.ToString("N2", CultureInfo.InvariantCulture);
101	}
