     1	// The one output format for agent code reviews (see .claude/skills/pr-review/SKILL.md).
     2	// The PR description copies these rows and adds a verdict to each, so the shape must not drift.
     3	
     4	export const REVIEW_TABLE_HEADER = '| ID | Severity | Category | Location | Finding | Suggested fix |';
     5	export const SEVERITIES = ['Blocker', 'Major', 'Minor', 'Nit'];
     6	
     7	/** Returns a list of problems; an empty list means the review is in the required format. */
     8	export function checkReviewFormat(message) {
     9	  const text = String(message ?? '');
    10	  const problems = [];
    11	  if (!/^## Review findings\s*$/m.test(text)) problems.push('Missing the "## Review findings" heading.');
    12	  if (!text.includes(REVIEW_TABLE_HEADER)) problems.push(`Missing the table header: ${REVIEW_TABLE_HEADER}`);
    13	
    14	  const rows = text.split(/\r?\n/).filter((line) => /^\|\s*R\d+\s*\|/.test(line));
    15	  for (const row of rows) {
    16	    const cells = row.replace(/\\\|/g, '/').split('|').slice(1, -1).map((cell) => cell.trim());
    17	    if (cells.length !== 6) problems.push(`Row ${cells[0]} has ${cells.length} cells; it needs 6.`);
    18	    else if (!SEVERITIES.includes(cells[1])) problems.push(`Row ${cells[0]} severity "${cells[1]}" must be one of ${SEVERITIES.join(', ')}.`);
    19	  }
    20	  if (rows.length === 0 && !/No findings\./.test(text)) problems.push('Add at least one R-numbered row, or write "No findings." under the table.');
    21	  return problems;
    22	}
